async function init(){try{S.countries=await loadJSON('data/countries.json');await reload();S.country=project()?.country||'USA';await render()}catch(e){if(e.status===401)login();else $('#app').innerHTML=`<div class="loading"><h2>Unable to open workspace</h2><p>${h(e.message)}</p>${btn('Try again','reload','reset')}</div>`}}
function login(){S.user=null;$('#app').innerHTML=`<main class="login"><div class="login-card"><div class="brand"><span class="brandmark">P</span>Property Map</div><h1>Welcome back.</h1><p class="sub">Sign in to your property workspace.</p><form id="loginForm" class="stack" aria-label="Sign in"><div id="formError"></div>${field('Work email','email','email','',true,'autocomplete="username"')}${field('Password','password','password','',true,'autocomplete="current-password"')}<button class="primary" type="submit">Sign in ${icon('arrow')}</button></form></div></main>`}
function shell(content){const p=project(),isShared=S.modeServer==='shared';return `<aside class="sidebar"><div class="brand"><span class="brandmark">P</span><span>Property Map</span></div><nav class="nav" aria-label="Main navigation">${nav('workspace','Map overview','map')}${nav('projects','Projects','folder')}${nav('properties','All properties','pin')}<div class="section-label">WORKSPACE</div>${nav('settings','Settings','settings')}</nav><div class="sidebar-bottom"><div class="storage-note">${isShared?'Shared workspace<br>Sign-in protection is enabled.':'Local preview<br>Data stays in this '+(window.STANDALONE?'browser.':'server.')}</div>${btn('Help & map sources','help','help','quiet small')}${isShared?btn('Sign out','logout','logout','quiet small'):''}</div></aside><main class="main"><header class="topbar"><div class="breadcrumb">Workspace ${icon('chevron')} ${h(S.view==='workspace'?p?.name||'Map overview':({projects:'Projects',properties:'All properties',settings:'Settings'}[S.view]))}</div><div class="topbar-right"><span class="hide-mobile"><span class="live-dot"></span> Workspace ready</span><span class="badge">${p?.demo?'Reference sample':'Your workspace'}</span></div></header><div class="page">${content}</div></main>`}
