function stat(label,num,foot,ico){return `<div class="stat"><div class="stat-top">${label}${icon(ico)}</div><div class="num">${num}</div><div class="foot">${foot}</div></div>`}
function enhanceSemantics(){$$('[data-action=mapmode]').forEach(b=>b.setAttribute('aria-pressed',String(b.classList.contains('active'))));const tabs=$('.settings-tabs');if(tabs){tabs.setAttribute('role','tablist');tabs.querySelectorAll('button').forEach(b=>{b.setAttribute('role','tab');b.setAttribute('aria-selected',String(b.classList.contains('active')))})}$$('table').forEach((table,i)=>{table.setAttribute('aria-label',table.closest('.panel')?.querySelector('h2,h3')?.textContent?.trim()||`Data table ${i+1}`);table.querySelectorAll('th').forEach(th=>th.setAttribute('scope','col'))});$$('.panelhead h3,.map-side h3,.settings-grid>.panel h3').forEach(hd=>{hd.setAttribute('role','heading');hd.setAttribute('aria-level','2')});if(S.user?.role!=='admin')$$('#accountForm input,#accountForm textarea,#accountForm select').forEach(el=>el.disabled=true);if($('#mapSvg')){$('#mapSvg').setAttribute('role','group');$('#mapSvg').setAttribute('aria-label','Interactive property map. Use arrow keys to move between regions.')}}
async function render(){if(!S.user)return;const p=project();if(!p&&['workspace','properties'].includes(S.view))S.view='projects';if(!p&&S.view==='settings'&&S.fieldScope!=='account')S.fieldScope='account';let content='';if(S.view==='workspace'||S.view==='properties'){activeGeo=await geo(S.country);content=workspaceUI(S.view==='properties')}else if(S.view==='projects')content=projectsView();else content=settingsViewUI();$('#app').innerHTML=shell(content);if(['workspace','properties'].includes(S.view)){if($('#mapSvg'))drawMap();}if(S.view==='projects')drawCards();enhanceSemantics()}
function workspace(listOnly=false){const p=project(),props=p.properties.filter(r=>r.country===S.country),c=counts();let list=filtered();const stateCount=Object.keys(c).length;const top=Object.entries(c).sort((a,b)=>b[1]-a[1]).slice(0,6);const actions=btn('Colors','colors','palette')+btn('Export','export','download')+btn('Add property','property','plus','primary',!canEdit()?'disabled':'');return header('PORTFOLIO INTELLIGENCE',listOnly?'Your properties':p.name,listOnly?'Every location. One organized view.':p.description,actions)+`<div class="stats">${stat('Total properties',props.length,'Across your selected country','pin')}${stat('Regions covered',stateCount,'States & provinces with properties','map')}${stat('Live properties',props.filter(r=>r.status==='Live').length,'Active in your portfolio','layers')}${stat('Opportunities',props.filter(r=>r.status==='Opportunity').length,'Room for what comes next','chart')}</div><section class="panel"><div class="panelhead"><div class="row">${icon('globe')}<h3>${listOnly?'Filter your portfolio':'Geographic overview'}</h3><span class="badge">${h(S.countries.find(x=>x.code===S.country)?.name)}</span></div>${!listOnly?`<div class="segmented" aria-label="Map mode">${['count','status','locations'].map((m,i)=>btn(['Property count','Regional status','Locations'][i],'mapmode','',''+(S.mapMode===m?'active':''),`data-mode="${m}"`)).join('')}</div>`:''}</div><div class="toolbar"><label>COUNTRY<select id="countryFilter" aria-label="Country filter">${countryOptions(S.country)}</select></label><label>STATE / PROVINCE<select id="stateFilter" aria-label="State filter">${options(regionNames(activeGeo),S.state,'All states / provinces')}</select></label><label>${S.country==='USA'?'COUNTY':'DISTRICT'}<select id="districtFilter" aria-label="District filter" ${!S.state?'disabled':''}>${options(districts(S.country,S.state),S.district,'All districts / counties')}</select></label><span class="spacer"></span>${S.state?btn('Clear filters','clear','','quiet small'):''}${!listOnly&&S.mapMode==='status'?btn('Region rules','region','edit','small',!canEdit()?'disabled':''):''}</div>${!listOnly?`<div class="map-layout"><div class="map-canvas"><svg id="mapSvg" role="img" aria-label="Interactive property map"></svg><div class="map-actions">${btn('','zoom-in','plus','iconbtn','aria-label="Zoom in"')}${btn('','zoom-out','minus','iconbtn','aria-label="Zoom out"')}${btn('','zoom-reset','reset','iconbtn','aria-label="Reset map"')}</div><div class="map-note">${S.mapMode==='locations'?'Only properties with entered coordinates are plotted.':'Select a region to explore its properties.'}</div></div><aside class="map-side"><div class="row between"><h3>Top regions</h3><span class="muted" style="font-size:10px">PROPERTIES</span></div>${top.length?top.map(([name,n],i)=>`<div class="region-rank" data-action="region-select" data-state="${h(name)}" role="button" tabindex="0"><span class="rank-index">0${i+1}</span><div class="rank-body">${h(name)}<div class="rank-line"><i style="width:${100*n/top[0][1]}%"></i></div></div><span class="rank-count">${n}</span></div>`).join(''):'<p class="sub">Add a property to begin your regional overview.</p>'}<div class="insight">${icon('spark')}<strong>${top.length?`${Math.round(top[0][1]/props.length*100)}% in ${h(top[0][0])}`:'Make your next move'}</strong>${top.length?'Your largest concentration of properties. Select a region to see the full picture.':'Your map comes to life as you add locations.'}</div></aside></div>${legend(p.palette)}`:''}</section>${propertyTable(list)}<div class="footer-note"><span>Made for a clearer view of your portfolio.</span><span>Natural Earth & US Census boundaries · ${props.length} properties in view</span></div>`}
function workspaceUI(listOnly=false){const colors=btn('Colors','colors','palette');return workspace(listOnly).replace(colors,btn('Legends','legends','layers')+colors).replace('Regional status','Map legends').replace(btn('Region rules','region','edit','small',!canEdit()?'disabled':''),btn('Manage legends','legends','edit','small',!canEdit()?'disabled':''))}
function districts(country,state){if(!state)return [];if(country==='USA'&&S.us){const st=topojson.feature(S.us,S.us.objects.states).features.find(x=>x.properties.name===state);return st?S.us.objects.counties.geometries.filter(x=>String(x.id).padStart(5,'0').slice(0,2)===String(st.id).padStart(2,'0')).map(x=>x.properties.name).sort():[]}return [...new Set(project().properties.filter(r=>r.country===country&&r.state===state&&r.district).map(r=>r.district))].sort()}
function legend(p){p=p?.palette?p:project();if(S.mapMode==='count')return `<div class="legend"><span>PROPERTY COUNT</span><div class="ramp">${[.1,.25,.45,.7,1].map(v=>`<i style="background:${d3.interpolateRgb('#f0ebf8',p.palette.Live)(v)}"></i>`).join('')}</div><span>Low → High</span><span><i style="--c:#eeeef1"></i>No properties</span><span class="spacer">Regional counts, not exact locations</span></div>`;return `<div class="legend">${projectLegends(p).map(item=>`<span><i style="--c:${item.color}"></i>${h(item.label)}</span>`).join('')}<span><i style="--c:${p.palette.Competition}"></i>Competition outline</span><span><i style="--c:#eeeef1"></i>Unclassified</span></div>`}
function makeProjection(g,code,w=900,hh=460){return (code==='USA'?d3.geoAlbersUsa():d3.geoMercator()).fitExtent([[25,20],[w-25,hh-28]],g)}
function drawMap(target='#mapSvg',code=S.country,mini=false,p=project()){
 const el=typeof target==='string'?$(target):target;if(!el)return;const g=S.geo[code];if(!g)return;
 const w=900,hh=460,pr=makeProjection(g,code,w,hh),path=d3.geoPath(pr);if(!mini)activeProjection=pr;
 const c={};p.properties.filter(r=>r.country===code).forEach(r=>c[r.state]=(c[r.state]||0)+1);const max=Math.max(1,...Object.values(c));
 const fill=f=>{const name=f.properties.name;if(mini||S.mapMode==='count')return c[name]?d3.interpolateRgb('#e6ddf7',p.palette.Live)(Math.sqrt(c[name]/max)):'#eeeef1';if(S.mapMode==='locations')return '#eeebf4';const lid=regionLegendId(p,code,name);return lid?(legendItem(lid,p)?.color||'#eeeef1'):'#eeeef1'};
 el.setAttribute('viewBox',`0 0 ${w} ${hh}`);el.innerHTML=`<g class="map-transform">${g.features.map(f=>{const n=f.properties.name,d=path(f);if(!d)return '';const pt=path.centroid(f),b=path.bounds(f),area=(b[1][0]-b[0][0])*(b[1][1]-b[0][1]);const label=mini?'':f.properties.abbr||abbr(n);const count=c[n]||0;return `<path class="region ${!mini&&S.state===n?'selected':''}" d="${d}" fill="${fill(f)}" ${mini?'':`data-state="${h(n)}" tabindex="0" role="button" aria-label="${h(n)}, ${count} properties"`} style="${(p.regionRules?.[code+':'+n]?.competition||p.properties.some(r=>r.country===code&&r.state===n&&r.competitor))?'stroke:'+p.palette.Competition+';stroke-width:2;':''}"/><g transform="translate(${pt[0]},${pt[1]})">${!mini&&area>1900&&Number.isFinite(pt[0])?`<text text-anchor="middle" y="${count&&S.mapMode==='count'?-5:3}" font-size="11" fill="${count&&S.mapMode!=='locations'?'#ffffff':'#9f96ab'}" font-weight="600">${h(label)}</text>${count&&S.mapMode==='count'?`<rect x="-11" y="3" width="22" height="18" rx="5" fill="#ffffffed"/><text text-anchor="middle" y="16" font-size="11" fill="${p.palette.Live}" font-weight="700">${count}</text>`:''}`:''}</g>`}).join('')}${!mini&&S.mapMode==='locations'?p.properties.filter(r=>r.country===code&&r.lat!==''&&r.lng!==''&&(!S.state||r.state===S.state)).map(r=>{const pt=pr([Number(r.lng),Number(r.lat)]),color=legendItem(propertyLegendId(r,p),p)?.color||p.palette[r.status];return pt?`<circle cx="${pt[0]}" cy="${pt[1]}" r="5.5" fill="${color}" stroke="white" stroke-width="2" data-property="${r.id}" tabindex="0" role="button" aria-label="${h(r.name)}"/>`:''}).join(''):''}</g>`;
 if(!mini){el.setAttribute('role','group');const svg=d3.select(el),zoom=d3.zoom().scaleExtent([1,8]).on('zoom',event=>svg.select('.map-transform').attr('transform',event.transform));svg.call(zoom);el._zoom=zoom;const regions=[...el.querySelectorAll('[data-state]')],active=Math.max(0,regions.findIndex(n=>n.dataset.state===S.state));regions.forEach((node,i)=>{const count=c[node.dataset.state]||0;node.tabIndex=i===active?0:-1;node.setAttribute('aria-label',`${node.dataset.state}, ${count} ${count===1?'property':'properties'}`);const label=node.nextElementSibling?.querySelector('text');if(label&&count&&S.mapMode!=='locations')label.setAttribute('fill',contrastText(node.getAttribute('fill')));node.addEventListener('click',()=>selectRegion(node.dataset.state));node.addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();selectRegion(node.dataset.state);return}let next;if(['ArrowRight','ArrowDown'].includes(e.key))next=(i+1)%regions.length;if(['ArrowLeft','ArrowUp'].includes(e.key))next=(i-1+regions.length)%regions.length;if(e.key==='Home')next=0;if(e.key==='End')next=regions.length-1;if(next!==undefined){e.preventDefault();regions.forEach(n=>n.tabIndex=-1);regions[next].tabIndex=0;regions[next].focus()}});node.addEventListener('pointerenter',e=>showTip(e,`${node.dataset.state} · ${count} ${count===1?'property':'properties'}`));node.addEventListener('pointerleave',hideTip)});el.querySelectorAll('[data-property]').forEach(n=>{n.tabIndex=-1;n.addEventListener('click',()=>propertyDrawer(n.dataset.property))})}
}
const AB={Alabama:'AL',Alaska:'AK',Arizona:'AZ',Arkansas:'AR',California:'CA',Colorado:'CO',Connecticut:'CT',Delaware:'DE',Florida:'FL',Georgia:'GA',Hawaii:'HI',Idaho:'ID',Illinois:'IL',Indiana:'IN',Iowa:'IA',Kansas:'KS',Kentucky:'KY',Louisiana:'LA',Maine:'ME',Maryland:'MD',Massachusetts:'MA',Michigan:'MI',Minnesota:'MN',Mississippi:'MS',Missouri:'MO',Montana:'MT',Nebraska:'NE',Nevada:'NV','New Hampshire':'NH','New Jersey':'NJ','New Mexico':'NM','New York':'NY','North Carolina':'NC','North Dakota':'ND',Ohio:'OH',Oklahoma:'OK',Oregon:'OR',Pennsylvania:'PA','Rhode Island':'RI','South Carolina':'SC','South Dakota':'SD',Tennessee:'TN',Texas:'TX',Utah:'UT',Vermont:'VT',Virginia:'VA',Washington:'WA','West Virginia':'WV',Wisconsin:'WI',Wyoming:'WY'};function abbr(n){return AB[n]||n.slice(0,3).toUpperCase()}
function showTip(e,text){hideTip();const d=document.createElement('div');d.className='tooltip';d.textContent=text;d.style.left=e.clientX+12+'px';d.style.top=e.clientY-35+'px';document.body.append(d)}function hideTip(){$$('.tooltip').forEach(x=>x.remove())}
async function selectRegion(name){S.state=S.state===name?'':name;S.district='';S.page=1;hideTip();await render()}
function propertyTable(rows){const pages=Math.max(1,Math.ceil(rows.length/8));S.page=Math.min(Math.max(1,S.page),pages);const pageRows=rows.slice((S.page-1)*8,S.page*8);return `<section class="panel properties-panel"><div class="panelhead"><div class="row"><h2>${S.state?h(S.state)+' properties':'Property directory'}</h2><span class="badge">${rows.length}</span></div><div class="row"><div class="searchbox">${icon('search')}<input id="propertySearch" aria-label="Search properties" placeholder="Search properties…" value="${h(S.search)}"></div>${btn('CSV','csv','download','quiet small')}</div></div>${rows.length?`<div class="table-wrap"><table class="table"><thead><tr><th>PROPERTY NAME</th><th>PROPERTY CODE</th><th>STATE / PROVINCE</th><th>STATUS</th><th>TEAM</th><th aria-label="Actions"></th></tr></thead><tbody>${pageRows.map(r=>`<tr><td><strong>${h(r.name)}</strong></td><td>${h(r.code)}</td><td>${h(r.state)}</td><td><span class="status ${r.status==='Opportunity'?'opportunity':''}"><span class="live-dot" style="background:${project().palette[r.status]}"></span>${h(r.status)}</span></td><td>${h(r.team)}</td><td>${btn('', 'property',canEdit()?'edit':'chevron','quiet iconbtn',`data-id="${r.id}" aria-label="${canEdit()?'Edit':'View'} ${h(r.name)}"`)}</td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>Showing ${(S.page-1)*8+1}–${Math.min(S.page*8,rows.length)} of ${rows.length} properties</span><div class="row">${btn('Previous','prev','','small',S.page<=1?'disabled':'')}<span>${S.page} / ${pages}</span>${btn('Next','next','','small',S.page>=pages?'disabled':'')}</div></div>`:`<div class="empty">${icon('pin')}<h2>No properties here yet</h2><p>Add your first property or adjust the filters.</p></div>`}</section>`}
function projectsView(){const list=S.projects.filter(p=>!S.projectSearch||[p.name,p.team].join(' ').toLowerCase().includes(S.projectSearch.toLowerCase()));return header('YOUR WORKSPACE','A place for every project','Build a portfolio. Explore a market. Bring your teams together.',btn('New project','new-project','plus','primary'))+`<div class="row between"><div class="row"><h2>All projects</h2><span class="badge">${S.projects.length}</span></div><div class="searchbox">${icon('search')}<input id="projectSearch" aria-label="Search projects" placeholder="Find a project…" value="${h(S.projectSearch||'')}"></div></div><div class="project-grid">${list.map(p=>`<article class="project-card"><div class="project-art"><svg data-card="${p.id}" role="img" aria-label="${h(p.name)} map preview"></svg><span class="badge">${h(p.team)}</span></div><div class="project-body"><h2>${h(p.name)}</h2><p>${h(p.description)}</p><div class="row muted" style="font-size:11px">${icon('pin')}${p.properties.length} properties <span>·</span>${new Set(p.properties.map(r=>r.country+':'+r.state)).size} regions</div><footer><span>${p.demo?'Sample project':h(access(p))+' access'}</span><span class="row">${access(p)==='admin'?btn('Settings','edit-project','edit','quiet small',`data-id="${p.id}"`):''}${btn('Open','open-project','arrow','quiet small',`data-id="${p.id}"`)}</span></footer></div></article>`).join('')}<button class="new-card" data-action="new-project"><div><span class="plus-circle">${icon('plus')}</span><h2>Start something new</h2><p>Create a project for your next big idea.</p></div></button></div>${exportsTable()}`}
async function drawCards(){for(const p of S.projects){await geo(p.country);drawMap($(`[data-card="${p.id}"]`),p.country,true,p)}}
function exportsTable(){const es=S.projects.flatMap(p=>p.exports.map(e=>({...e,project:p.name,projectId:p.id,canDelete:access(p)==='admin'}))).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,8);return `<section class="panel properties-panel"><div class="panelhead"><h2>Recent exports</h2><span class="muted" style="font-size:11px">Saved snapshots of your work</span></div>${es.length?`<div class="table-wrap"><table class="table"><thead><tr><th>FILE</th><th>PROJECT</th><th>EXPORTED</th><th aria-label="Actions"></th></tr></thead><tbody>${es.map(e=>`<tr><td><strong>${h(e.name)}</strong></td><td>${h(e.project)}</td><td>${date(e.date)}</td><td><span class="row">${btn('Download','download-export','download','quiet small',`data-id="${e.id}"`)}${e.canDelete?btn('Delete','delete-export','trash','quiet danger small',`data-id="${e.id}" data-project="${e.projectId}"`):''}</span></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h2>Your exports will live here</h2><p>Export a map as PNG or PDF and save a dated snapshot to a project.</p></div>'}</section>`}
function field(label,name,type='text',value='',required=false,extra=''){return `<label class="field ${type==='textarea'?'full':''}"><span>${h(label)}${required?' <span style="color:#b2899e">*</span>':''}</span>${type==='textarea'?`<textarea name="${name}" ${required?'required':''} ${extra}>${h(value)}</textarea>`:`<input name="${name}" type="${type}" value="${h(value)}" ${required?'required':''} ${extra}>`}</label>`}
function selectField(label,name,opts,required=false,extra=''){return `<label class="field"><span>${h(label)}${required?' *':''}</span><select name="${name}" ${required?'required':''} ${extra}>${opts}</select></label>`}
function customInput(f,v='',disabled=false){const extra=disabled?'disabled':'';if(f.type==='checkbox')return `<label class="row" style="font-size:12px"><input name="custom_${f.id}" type="checkbox" ${v?'checked':''} ${f.required?'required':''} ${extra}>${h(f.label)}${f.required?' *':''}</label>`;if(f.type==='select')return selectField(f.label,'custom_'+f.id,options(f.options||[],v,'Select…'),f.required,extra);return field(f.label,'custom_'+f.id,f.type,v,f.required,extra)}
function drawer(title,subtitle,body,footer='',wide=false,dialog=false){lastFocus=document.activeElement;$('#app').inert=true;$('#overlay').innerHTML=`<div class="overlay-backdrop" data-action="close"></div><section class="${dialog?'dialog':'drawer'+(wide?' wide':'')}" role="dialog" aria-modal="true" aria-labelledby="drawerTitle" aria-describedby="drawerDescription"><div class="drawer-header"><div class="row between"><h2 id="drawerTitle">${title}</h2>${btn('','close','close','quiet iconbtn','aria-label="Close panel"')}</div><p class="sub" id="drawerDescription">${subtitle}</p></div><div class="drawer-body">${body}</div>${footer?`<div class="drawer-footer">${footer}</div>`:''}</section>`;const form=$('#overlay form');S.drawerInitial=form?new URLSearchParams(new FormData(form)).toString():null;document.body.style.overflow='hidden';setTimeout(()=>$('#overlay input:not([type=hidden]), #overlay select, #overlay button')?.focus(),20)}
function closeDrawer(force=false){const form=$('#overlay form'),changed=form&&S.drawerInitial!==new URLSearchParams(new FormData(form)).toString();if(!force&&changed&&!confirm('Discard your unsaved changes?'))return false;S.drawer=null;S.drawerInitial=null;$('#overlay').innerHTML='';$('#app').inert=false;document.body.style.overflow='';lastFocus?.focus();return true}
function showError(e){if(e?.status===401){closeDrawer(true);login();toast('Your session expired. Sign in again to continue.');return}const box=$('#formError');if(box){box.className='form-error';box.setAttribute('role','alert');box.setAttribute('aria-live','assertive');box.textContent=e.message}else toast(e.message)}
async function propertyDrawer(pid){const p=project(),r=p.properties.find(x=>x.id===pid)||{id:id(),name:'',code:'',country:S.country,state:S.state,district:'',city:'',address:'',status:'Live',team:p.team,notes:'',lat:'',lng:'',competitor:false,custom:{}};S.editing=clone(r);S.editingExisting=!!pid;S.drawer='property';await geo(r.country);drawer(pid?(canEdit()?'Edit property':'Property details'):'Add a property',h(p.name),`<form id="propertyForm"><div id="formError"></div><div class="field-grid">${field('Property name','name','text',r.name,true,'maxlength="120"')}${field('Property code','code','text',r.code,true,'maxlength="50"')}${selectField('Country','country',countryOptions(r.country),true)}${selectField('State / Province','state',options(regionNames(S.geo[r.country]),r.state,'Select a state'),true)}<div id="districtField">${districtField(r.country,r.state,r.district)}</div>${field('City','city','text',r.city)}<div class="field full">${field('Street address','address','text',r.address)}</div>${selectField('Property status','status',options(['Live','Opportunity'],r.status),true)}${selectField('Owning team','team',options(S.config.teams||[],r.team))}${field('Latitude','lat','number',r.lat,false,'min="-90" max="90" step="any" placeholder="Optional"')}${field('Longitude','lng','number',r.lng,false,'min="-180" max="180" step="any" placeholder="Optional"')}<div class="hint full" style="grid-column:1/-1">Coordinates are optional. Only entered coordinates appear as exact map locations.</div><label class="row full"><input type="checkbox" name="competitor" ${r.competitor?'checked':''}>Competitor property</label><div id="customFields" class="field-grid full" style="grid-column:1/-1">${renderCustomFields(r)}</div>${field('Notes','notes','textarea',r.notes)}</div></form>`,`${pid&&canEdit()?btn('Delete','delete-property','trash','quiet danger','data-id="'+r.id+'"'):''}<span class="spacer"></span>${btn('Cancel','close')}${canEdit()?'<button class="primary" type="submit" form="propertyForm">Save property</button>':''}`);if(!canEdit())$('#propertyForm').querySelectorAll('input,select,textarea').forEach(e=>e.disabled=true)}
function districtField(country,state,value){if(country==='USA')return selectField('County','district',options(districts(country,state),value,'Optional'),false,!state?'disabled':'');return field('District / County','district','text',value,false,'placeholder="Enter district (optional)"')}
function renderCustomFields(r){return getFields().filter(f=>fieldAllowed(f)&&(!f.condition||f.condition===r.status)).map(f=>customInput(f,r.custom?.[f.id]??'',!fieldAllowed(f,'editable'))).join('')}
async function submitProperty(form){const fd=new FormData(form),r={...S.editing};for(const k of ['name','code','country','state','district','city','address','status','team','notes','lat','lng'])r[k]=String(fd.get(k)||'').trim();r.competitor=fd.has('competitor');r.custom={...r.custom};getFields().forEach(f=>{if(fieldAllowed(f,'editable')&&(!f.condition||f.condition===r.status))r.custom[f.id]=f.type==='checkbox'?fd.has('custom_'+f.id):fd.get('custom_'+f.id)||''});const p=clone(project());if(p.properties.some(x=>x.id!==r.id&&x.code.toLowerCase()===r.code.toLowerCase()))throw Error('This property code already exists in the project.');if((r.lat==='')!==(r.lng===''))throw Error('Enter both latitude and longitude.');if(S.editingExisting)p.properties=p.properties.map(x=>x.id===r.id?r:x);else p.properties.push(r);await saveProject(p,S.editingExisting?'Property updated':'Property added to your project');closeDrawer(true);await render()}
const basePropertyDrawer=propertyDrawer,baseSubmitProperty=submitProperty;
propertyDrawer=async function(pid){await basePropertyDrawer(pid);const form=$('#propertyForm');if(!form)return;const item=project().properties.find(x=>x.id===pid)||S.editing;item.legendId=propertyLegendId(item);const control=selectField('Map legend','legendId',options(projectLegends().map(x=>({value:x.id,label:x.label})),item.legendId),true);form.elements.status.closest('label').insertAdjacentHTML('afterend',control);if(!canEdit())form.elements.legendId.disabled=true;S.drawerInitial=new URLSearchParams(new FormData(form)).toString()}
submitProperty=async function(form){S.editing.legendId=String(new FormData(form).get('legendId')||projectLegends()[0]?.id||'');return baseSubmitProperty(form)}
function projectDrawer(pid){const p=S.projects.find(x=>x.id===pid);if(!p)return newProject();S.editingProject=pid;S.drawer='project';drawer('Project settings','Update project details or remove this project.',`<form id="projectForm" class="stack"><div id="formError"></div>${field('Project name','name','text',p.name,true,'maxlength="100"')}${field('Description','description','textarea',p.description,false,'maxlength="2000"')}${selectField('Starting country','country',countryOptions(p.country),true)}${selectField('Owning team','team',options(S.config.teams,p.team),true)}<div class="hint">Changing the starting country does not move or delete existing properties.</div></form>`,btn('Delete project','delete-project','trash','quiet danger',`data-id="${p.id}"`)+`<span class="spacer"></span>`+btn('Cancel','close')+'<button form="projectForm" class="primary">Save project</button>',false,true)}
function newProject(){S.editingProject=null;S.drawer='project';drawer('A new beginning','Create a project for your portfolio or next opportunity.',`<form id="projectForm" class="stack"><div id="formError"></div>${field('Project name','name','text','',true,'maxlength="100" placeholder="e.g. Northeast Expansion"')}${field('Description','description','textarea','',false,'maxlength="2000" placeholder="What is this project about?"')}${selectField('Starting country','country',countryOptions(S.country||'USA'),true)}${selectField('Owning team','team',options(S.config.teams,S.user.team),true)}</form>`,btn('Cancel','close')+'<button form="projectForm" class="primary">Create project</button>',false,true)}
async function submitProject(form){const fd=new FormData(form);if(S.editingProject){const p=clone(S.projects.find(x=>x.id===S.editingProject));p.name=fd.get('name').trim();p.description=fd.get('description').trim();p.team=fd.get('team');p.country=fd.get('country');const saved=await saveProject(p,'Project updated');if(S.project===saved.id)S.country=saved.country;closeDrawer(true);S.view='projects';return render()}const palette=clone(S.config.palette||paletteFrom(PRESETS.Classic)),p={name:fd.get('name').trim(),description:fd.get('description').trim(),team:fd.get('team'),country:fd.get('country'),palette,legends:defaultLegends(palette),fields:[],regionRules:{},properties:[],exports:[],demo:false};const saved=await api('/api/projects','POST',p);S.projects.push(saved);S.project=saved.id;S.country=saved.country;S.state='';S.district='';S.search='';S.view='workspace';closeDrawer(true);toast('Your new project is ready');await render()}
function colorsDrawer(){S.drawer='colors';S.colorDraft=clone(project().palette);S.generated=null;drawer('Color studio','Make your map feel like your own.',`<div id="formError"></div><div class="section-title">01 / Preset palettes</div><div class="palette-cards">${Object.entries(PRESETS).map(([n,a])=>`<button class="palette-card" data-action="preset" data-preset="${n}"><span>${n}</span><div class="swatches">${a.map(c=>`<span style="background:${c}"></span>`).join('')}</div></button>`).join('')}</div><div class="section-title">02 / Generate a palette</div><label class="field"><span>Describe a mood</span><input id="palettePrompt" placeholder="Calm ocean, warm earth, vibrant…"><small>Generated locally using color harmony rules. No AI service connected.</small></label><div class="row" style="margin-top:10px">${btn('Generate palette','generate-palette','spark','small')}</div><div id="generatedPalette"></div><div class="section-title row between">03 / Custom colors ${btn('Reset','reset-colors','','quiet small')}</div><div id="colorInputs">${colorInputs()}</div><div class="hint">Category labels stay unchanged when you change colors. The palette is included in PNG and PDF exports.</div><div class="section-title">Save palette to</div><select id="paletteScope" aria-label="Palette scope">${options([{value:'project',label:'This project'},{value:'account',label:'Account default + this project'}],'project')}</select>`,btn('Cancel','close')+btn('Apply colors','apply-colors','check','primary',!canEdit()?'disabled':''))}
function colorInputs(){return COLOR_KEYS.map(k=>`<div class="color-row"><span>${k==='Live'?'Live properties':k}</span><input type="color" data-color="${k}" value="${S.colorDraft[k]}" aria-label="${k} color"><input type="text" data-hex="${k}" value="${S.colorDraft[k]}" aria-label="${k} hex code" pattern="#[0-9a-fA-F]{6}"></div>`).join('')}
function generatePalette(){const prompt=$('#palettePrompt').value.toLowerCase();let hue=/ocean|blue|calm|cool/.test(prompt)?210:/earth|forest|green|natural/.test(prompt)?130:/warm|sun|orange/.test(prompt)?28:/pink|rose/.test(prompt)?330:/purple|violet/.test(prompt)?270:Math.random()*360;hue+=Math.random()*18-9;const c=(h,s,l)=>d3.hsl(h,s,l).formatHex();S.generated=[c(hue,.48,.49),c(hue+65,.43,.45),c(hue+175,.58,.51),'#cfd5df',c(hue+115,.35,.59)];$('#generatedPalette').innerHTML=`<div class="generated"><small>YOUR GENERATED PALETTE</small><div class="row"><div class="swatches" style="flex:1">${S.generated.map(c=>`<span style="background:${c}"></span>`).join('')}</div>${btn('Use palette','use-generated','','small')}</div></div>`}
function refreshColorInputs(){$('#colorInputs').innerHTML=colorInputs()}
function scopedFields(){if(S.fieldScope==='account')return S.config.fields||[];if(S.fieldScope==='team')return S.config.teamFields?.[project()?.team]||[];return project()?.fields||[]}
function settingsView(){const isAdmin=S.user.role==='admin';let body='';if(S.settingsTab==='fields'){body=`<div class="settings-grid"><section class="panel"><div class="panelhead"><div><h3>Property fields</h3><p class="sub">Flexible forms, consistent data.</p></div>${btn('Add field','add-field','plus','primary small',!isAdmin?'disabled':'')}</div><div class="toolbar"><label>CONFIGURATION SCOPE<select id="fieldScope">${options([{value:'account',label:'Account defaults'},{value:'team',label:'Team: '+(project()?.team||'No project')},{value:'project',label:'Project: '+(project()?.name||'No project')}],S.fieldScope)}</select></label><span class="badge">${isAdmin?'Admin':'Read only'}</span></div><div class="table-wrap"><table class="table"><thead><tr><th>FIELD</th><th>TYPE</th><th>REQUIRED</th><th>VISIBLE TO</th><th></th></tr></thead><tbody>${['Property name','Property code','Country','State / Province'].map(n=>`<tr><td><strong>${n}</strong></td><td>${n.includes('Country')||n.includes('State')?'Location':'Text'}</td><td>${icon('check')}</td><td>Everyone</td><td>${icon('lock')}</td></tr>`).join('')}${scopedFields().map(f=>`<tr><td><strong>${h(f.label)}</strong></td><td>${h(f.type)}</td><td>${f.required?icon('check'):'Optional'}</td><td>${h(f.visibility||'everyone')}</td><td>${btn('','edit-field','edit','quiet iconbtn',`data-id="${f.id}" aria-label="Edit ${h(f.label)}" ${!isAdmin?'disabled':''}`)}</td></tr>`).join('')}</tbody></table></div><div style="padding:20px"><div class="hint">Account defaults → Team settings → Project overrides.<br>Required core fields and locked account fields stay protected.</div></div></section><aside class="panel form-preview"><div class="row between"><h3>Form preview</h3><span class="badge">Admin</span></div><p class="sub" style="margin-bottom:22px">${h(project()?.name||'New project')}</p><div class="stack">${field('Property name','preview_name','text','Aria',true,'disabled')}${field('Property code','preview_code','text','V227',true,'disabled')}${getFields().map(f=>customInput(f,'',true)).join('')}${!getFields().length?'<p class="sub">Custom fields will appear here.</p>':''}</div></aside></div>`}else if(S.settingsTab==='account')body=`<section class="panel" style="max-width:750px"><div class="panelhead"><h3>Account preferences</h3></div><form id="accountForm" class="stack" style="padding:25px"><div id="formError"></div>${field('Organization name','accountName','text',S.config.accountName,true)}${field('Display name (local preview)','displayName','text',S.config.displayName||S.user.name,true)}${field('Teams (one per line)','teams','textarea',S.config.teams.join('\n'),true)}<button class="primary" style="align-self:flex-start" ${!isAdmin?'disabled':''}>Save preferences</button></form></section>`;else body=`<section class="panel" style="max-width:850px"><div class="panelhead"><h3>Your data, in your hands</h3></div><div class="stack" style="padding:25px"><p class="sub">Download a portable JSON backup of the projects and fields you can access. Exported PNG/PDF files are downloaded separately.</p><div class="row">${btn('Download backup','backup','download')}${btn('Import project backup','import','folder')}</div><input id="importFile" type="file" accept=".json,application/json" hidden><div class="hint">Imports create new projects, leaving existing work intact. Geographic data is bundled for offline use. District boundaries are currently bundled for the United States; other countries support manual district entry.</div></div></section>`;return header('WORKSPACE SETTINGS','Designed around your team','Manage your fields, preferences, and workspace data.')+`<div class="settings-tabs">${['fields','account','data'].map((t,i)=>btn(['Property fields','Account preferences','Data & backups'][i],'settings-tab','',S.settingsTab===t?'active':'',`data-tab="${t}"`)).join('')}</div>`+body}
function settingsViewUI(){const tabs=`<div class="settings-tabs">${['fields','account','data'].map((t,i)=>btn(['Property fields','Teams','Data & backups'][i],'settings-tab','',S.settingsTab===t?'active':'',`data-tab="${t}"`)).join('')}</div>`;if(S.settingsTab==='account'){const isAdmin=S.user.role==='admin';return header('WORKSPACE SETTINGS','Workspace configuration','Manage teams without exposing user or account details.')+tabs+`<section class="panel" style="max-width:750px"><div class="panelhead"><h3>Teams</h3></div><form id="teamForm" class="stack" style="padding:25px"><div id="formError"></div>${field('Teams (one per line)','teams','textarea',S.config.teams.join('\n'),true)}<button class="primary" style="align-self:flex-start" ${!isAdmin?'disabled':''}>Save teams</button></form></section>`}return settingsView().replace('Account preferences','Teams').replaceAll('Account defaults','Workspace defaults').replace('Designed around your team','Workspace configuration').replace('Manage your fields, preferences, and workspace data.','Manage fields, teams, legends, and workspace data.')}
function fieldDrawer(fid){const f=scopedFields().find(x=>x.id===fid)||{id:id().replaceAll('-','').slice(0,16),label:'',type:'text',required:false,visibility:'everyone',editable:'everyone',options:[],condition:'',locked:false};S.fieldDraft=clone(f);S.drawer='field';drawer(fid?'Edit field':'Add a custom field',`Scope: ${h(S.fieldScope==='account'?'Workspace defaults':S.fieldScope==='team'?project().team:project().name)}`,`<form id="fieldForm" class="stack"><div id="formError"></div>${field('Field label','label','text',f.label,true,'maxlength="80" placeholder="e.g. Site capacity"')}${selectField('Field type','type',options(['text','number','date','select','checkbox'],f.type),true)}${field('Dropdown options (one per line)','options','textarea',f.options.join('\n'))}<div class="field-grid">${selectField('Visible to','visibility',options(['everyone','contributors','admins'],f.visibility))}${selectField('Editable by','editable',options(['everyone','contributors','admins'],f.editable))}</div>${selectField('Show when property status is','condition',options(['Live','Opportunity'],f.condition,'Always'))}<label class="row"><input type="checkbox" name="required" ${f.required?'required':''} ${f.required?'checked':''}>Required field</label>${S.fieldScope==='account'?`<label class="row"><input type="checkbox" name="locked" ${f.locked?'checked':''}>Lock for teams and projects</label>`:''}<div class="hint">Required fields must be editable by the roles that can see them. Existing values are preserved when a field is hidden.</div></form>`,`${fid?btn('Remove field','remove-field','trash','quiet danger',`data-id="${f.id}"`):''}<span class="spacer"></span>${btn('Cancel','close')}<button form="fieldForm" class="primary">Save field</button>`)}
const baseFieldDrawer=fieldDrawer;
fieldDrawer=function(fid){baseFieldDrawer(fid);$('#fieldForm [name=required]')?.removeAttribute('required');S.drawerInitial=new URLSearchParams(new FormData($('#fieldForm'))).toString()}
async function saveFieldList(fs){if(S.fieldScope==='project'){const p=clone(project());p.fields=fs;await saveProject(p,'Field configuration saved')}else{const cfg=clone(S.config);if(S.fieldScope==='account')cfg.fields=fs;else{cfg.teamFields??={};cfg.teamFields[project().team]=fs}await api('/api/config','PUT',cfg);S.config=cfg;toast('Field configuration saved')}closeDrawer(true);await render()}
function teamView(){return header('PEOPLE & PERMISSIONS','Better, together','Manage who can view and contribute to your projects.',btn('Add account','add-user','plus','primary',window.STANDALONE||S.user.role!=='admin'?'disabled':''))+`<div class="hint" style="margin-bottom:22px">${S.modeServer==='shared'?'Project access is enforced by the server. Contributors can manage properties; viewers can browse and export.':'You are viewing the local edition. The server package includes password sign-in and enforced project permissions for shared hosting. No invitations or messages are sent.'}</div><section class="panel"><div class="panelhead"><h3>Workspace accounts</h3><span class="badge">${h(S.config.accountName)}</span></div><div id="userList"><div class="empty">Loading accounts…</div></div></section><section class="panel properties-panel"><div class="panelhead"><h3>Project access</h3></div><div class="table-wrap"><table class="table"><thead><tr><th>PROJECT</th><th>TEAM</th><th>YOUR ACCESS</th><th></th></tr></thead><tbody>${S.projects.map(p=>`<tr><td><strong>${h(p.name)}</strong></td><td>${h(p.team)}</td><td>${h(access(p))}</td><td>${btn('Manage access','share','users','small',`data-id="${p.id}"`)}</td></tr>`).join('')}</tbody></table></div></section>`}
async function loadUsers(){try{S.users=window.STANDALONE?[S.user]:await api('/api/users');const el=$('#userList');if(el)el.innerHTML=`<table class="table"><thead><tr><th>PERSON</th><th>EMAIL</th><th>ROLE</th><th>TEAM</th></tr></thead><tbody>${S.users.map(u=>`<tr><td><strong>${h(u.name)}</strong></td><td>${h(u.email)}</td><td>${h(u.role)}</td><td>${h(u.team)}</td></tr>`).join('')}</tbody></table>`}catch(e){if($('#userList'))$('#userList').innerHTML=`<div class="empty">${h(e.message)}</div>`}}
function userDrawer(){drawer('Add workspace account','Create sign-in access. No invitation email is sent.',`<form id="userForm" class="stack"><div id="formError"></div>${field('Full name','name','text','',true)}${field('Work email','email','email','',true)}${field('Initial password','password','password','',true,'minlength="12" autocomplete="new-password"')}${selectField('Account role','role',options(['member','admin'],'member'))}${selectField('Team','team',options(S.config.teams,S.user.team))}<div class="hint">Use a unique password of at least 12 characters. Share credentials through your organization’s approved channel.</div></form>`,btn('Cancel','close')+'<button form="userForm" class="primary">Create account</button>')}
async function shareDrawer(pid){const p=S.projects.find(x=>x.id===(pid||S.project));if(window.STANDALONE||S.user.role!=='admin'){drawer('Project access',h(p.name),`<div class="hint">${window.STANDALONE?'Shared access requires the authenticated server edition. This browser preview does not grant access to other people.':'Ask a workspace administrator to manage account assignments.'}</div>`,btn('Close','close'));return}S.shareProject=p.id;const users=await api('/api/users');drawer('Project access',h(p.name),`<form id="shareForm" class="stack"><div id="formError"></div><div class="hint">Owners and workspace admins always have access. Select the role for each other account.</div>${users.filter(u=>u.role!=='admin'&&u.id!==p.owner).map(u=>selectField(u.name+' · '+u.email,'member_'+u.id,options([{value:'',label:'No access'},{value:'viewer',label:'Viewer'},{value:'contributor',label:'Contributor'}],p.members?.[u.id]||''))).join('')||'<p class="sub">Add a workspace member in Team & access first.</p>'}</form>`,btn('Cancel','close')+'<button class="primary" form="shareForm">Save access</button>')}
function legendAssignments(p=project()){return Object.entries(p.regionRules||{}).filter(([,rule])=>rule.legendId).map(([key,rule])=>{const cut=key.indexOf(':');return {key,country:key.slice(0,cut),state:key.slice(cut+1),rule}}).sort((a,b)=>a.country.localeCompare(b.country)||a.state.localeCompare(b.state))}
async function legendsDrawer(country=S.legendCountry||S.country,state=S.legendState||S.state){const p=project();ensureProjectLegends(p);country=country||p.country;await geo(country);const states=regionNames(S.geo[country]);if(!states.includes(state))state='';S.legendCountry=country;S.legendState=state;const categories=projectLegends(p).map(item=>{const usage=p.properties.filter(r=>propertyLegendId(r,p)===item.id).length+Object.values(p.regionRules||{}).filter(rule=>rule.legendId===item.id).length;return `<div class="legend-editor-row"><span class="legend-swatch" style="--c:${item.color}"></span><div><strong>${h(item.label)}</strong><small>${usage} assignment${usage===1?'':'s'}</small></div><span class="spacer"></span>${btn('Edit','edit-legend','edit','quiet small',`data-id="${item.id}"`)}${btn('Delete','delete-legend','trash','quiet danger small',`data-id="${item.id}" ${p.legends.length===1?'disabled':''}`)}</div>`}).join('');const assignments=legendAssignments(p).map(({key,country,state,rule})=>{const item=legendItem(rule.legendId,p),countryName=S.countries.find(x=>x.code===country)?.name||country;return `<div class="legend-editor-row"><span class="legend-swatch" style="--c:${item?.color||'#eeeef1'}"></span><div><strong>${h(state)}</strong><small>${h(countryName)} · ${h(item?.label||'Unknown')}${rule.competition?' · Competition outline':''}</small></div><span class="spacer"></span>${btn('Edit','edit-region-legend','edit','quiet small',`data-key="${h(key)}"`)}${btn('Remove','delete-region-legend','trash','quiet danger small',`data-key="${h(key)}"`)}</div>`}).join('')||'<p class="sub">No state or province assignments yet.</p>';drawer('Map legends','Create categories, then apply them to states or provinces.',`<div id="formError"></div><div class="section-title row between">Legend categories ${btn('Add legend','add-legend','plus','small')}</div><div class="legend-editor-list">${categories}</div><div class="section-title">Apply a legend to a region</div><form id="legendAssignForm" class="stack"><div class="field-grid">${selectField('Country','country',countryOptions(country),true,'id="legendCountry"')}${selectField('State / Province','state',options(states,state,'Select a state or province'),true,'id="legendState"')}${selectField('Map legend','legendId',options(projectLegends(p).map(x=>({value:x.id,label:x.label})),p.regionRules?.[country+':'+state]?.legendId||projectLegends(p)[0].id),true)}<label class="row"><input type="checkbox" name="competition" ${p.regionRules?.[country+':'+state]?.competition?'checked':''}>Competition outline</label></div><button class="primary" style="align-self:flex-start">Apply to state / province</button></form><div class="section-title">Regional assignments</div><div class="legend-editor-list">${assignments}</div>`,btn('Done','close','','primary'),true)}
function legendDefinitionDrawer(legendId){const current=legendId?legendItem(legendId):null;S.editingLegend=legendId||null;drawer(current?'Edit map legend':'Add map legend',current?'Update the label or color everywhere it is used.':'Create another category for properties and regions.',`<form id="legendForm" class="stack"><div id="formError"></div>${field('Legend name','label','text',current?.label||'',true,'maxlength="80" placeholder="e.g. Under review"')}${field('Legend color','color','color',current?.color||'#7052d6',true)}<div class="hint">Legend names are unique within this project. Editing a legend updates all of its property and regional uses.</div></form>`,btn('Cancel','legends')+'<button class="primary" form="legendForm">Save legend</button>')}
function regionDrawer(){if(!S.state){toast('Select a state or province first');return}const key=S.country+':'+S.state,r=project().regionRules?.[key]||{};S.regionKey=key;drawer('Regional rules',h(S.state),`<form id="regionForm" class="stack"><div id="formError"></div>${selectField('Regional classification','status',options(['Live','Opportunity','No credit','Prohibited'],r.status,'Automatic (from properties)'))}<label class="row"><input type="checkbox" name="competition" ${r.competition?'checked':''}>Highlight competition with a colored outline</label><div class="hint">These rules apply to this region in this project. They do not change individual property records.</div></form>`,btn('Cancel','close')+'<button class="primary" form="regionForm">Save rule</button>')}
async function exportDrawer(){
 S.drawer='export';await geo(S.country);
 const all=project().properties.length;
 drawer('Export complete report','A map and a readable line for every property in the chosen scope.',
 `<form id="exportForm"><div id="formError"></div>
 <div class="export-preview"><div class="row between"><div><h3>${h(project().name)}</h3><small>${h(S.countries.find(c=>c.code===S.country)?.name)} map overview</small></div><span class="badge" id="exportPreviewBadge">COMPLETE DIRECTORY</span></div><div class="export-preview-layout" id="exportPreviewLayout"><svg id="exportPreview" aria-label="Map preview"></svg><div class="poster-preview-list" id="posterPreviewList"></div></div></div>
 <div class="export-summary"><strong id="exportCount">${all} of ${all} properties included</strong><span id="exportEstimate" class="muted"></span><button type="button" class="quiet small export-review" data-action="review-export-list">Review every included property ${icon('down')}</button></div>
 ${selectField('Which properties?','scope',options([{value:'all',label:`All ${all} project properties`},{value:'view',label:'Only the current filtered view'}],'all'),true,'id="exportScope"')}
 <div class="field-grid" style="margin-top:15px">${selectField('File format','format',options(['PDF','PNG'],'PDF'),true)}${selectField('Resolution','resolution',options([{value:'1920',label:'HD · standard detail'},{value:'3840',label:'4K · high detail'}],'3840'),true)}</div>
 <div id="pngLayoutField" style="display:none;margin-top:15px">${selectField('PNG layout','pngLayout',options([{value:'directory',label:'Map above complete directory'},{value:'poster',label:'Single image · map left, property list right'}],'directory'),true)}</div>
 <div class="checks"><label><input name="legend" type="checkbox" checked>Include map legend</label><label><input name="date" type="checkbox" checked>Include export date</label><label id="customFieldsChoice"><input name="customFields" type="checkbox" checked>Include configured fields in the directory</label></div>
 <div class="section-title">Save destination</div>${selectField('Project','destination',options([...S.projects.map(p=>({value:p.id,label:p.name})),{value:'new',label:'+ Create a new project'}],project().id))}<div id="newExportProject" style="display:none;margin-top:15px">${field('New project name','newProjectName','text','','','placeholder="Name your new project"')}</div>
 <div class="checks"><label><input name="download" type="checkbox" checked>Download a copy</label></div>
 <div class="hint" id="exportLayoutHint">Every included property has its own unwrapped row. Long values widen the report. PDF uses numbered pages; a very large PNG report becomes a ZIP of numbered PNG pages.</div>
 <div class="section-title">Included properties <span id="exportListCount" class="muted"></span></div><div id="exportRecords" class="export-records"></div>
 </form>`,btn('Cancel','close')+'<button class="primary" form="exportForm" id="exportButton">Export complete report</button>');
 drawMap('#exportPreview',S.country,true);refreshExportPlan();
}
function exportRows(form){return ExportEngine.rowsFor(project(),form.elements.scope.value,filtered())}
function exportColumns(rows,form){
 const names=Object.fromEntries(S.countries.map(c=>[c.code,c.name]));
 return ExportEngine.columnsFor(rows,form.elements.customFields.checked?getFields().filter(f=>fieldAllowed(f)):[],names);
}
function refreshExportPlan(){
 const form=$('#exportForm');if(!form)return;
 const rows=exportRows(form),all=project().properties.length,resolution=Number(form.elements.resolution.value);
 const poster=form.elements.format.value==='PNG'&&form.elements.pngLayout.value==='poster';
 $('#pngLayoutField').style.display=form.elements.format.value==='PNG'?'block':'none';
 $('#customFieldsChoice').style.display=poster?'none':'flex';
 $('#exportPreviewLayout').classList.toggle('poster',poster);
 $('#exportPreviewBadge').textContent=poster?'SINGLE IMAGE':'COMPLETE DIRECTORY';
 $('#posterPreviewList').innerHTML=poster?`<strong>Property list</strong><small>${rows.length} properties by region</small>${rows.slice(0,5).map(r=>`<span title="${h(r.code)} · ${h(r.name)}">${h(r.code)} · ${h(r.name)}</span>`).join('')}<em>+ ${Math.max(0,rows.length-5)} more in the full image</em>`:'';
 $('#exportLayoutHint').textContent=poster?'This single PNG keeps the map large on the left and groups every property code and full name by region on the right. The image grows or adds list columns as needed. Choose the complete directory layout for all configured fields.':'Every included property has its own unwrapped row. Long values widen the report. PDF uses numbered pages; a very large PNG report becomes a ZIP of numbered PNG pages.';
 $('#exportCount').textContent=`${rows.length} of ${all} project properties included`;
 $('#exportListCount').textContent=`(${rows.length} of ${all})`;
 const list=$('#exportRecords');
 list.innerHTML=rows.length?rows.map((r,i)=>`<div class="export-record"><span class="record-number">${String(i+1).padStart(2,'0')}</span><strong>${h(r.code)}</strong><span>${h(r.name)}</span><small>${h([S.countries.find(c=>c.code===r.country)?.name||r.country,r.state,r.district].filter(Boolean).join(' / '))}</small></div>`).join(''):'<div class="empty">No properties match the current filters.</div>';
 try{
  if(poster){
   const names=Object.fromEntries(S.countries.map(c=>[c.code,c.name]));
   const plan=ExportEngine.posterPlan(rows,names,resolution,project().name);
   $('#exportEstimate').textContent=`One PNG image · ${plan.columns.length} list columns · ${Math.ceil(plan.width*resolution/1920)} × ${Math.ceil(plan.height*resolution/1920)} px`;
  }else{
   const cols=exportColumns(rows,form);
   const n=form.elements.format.value==='PNG'?ExportEngine.pngPlan(rows.length,cols.width,resolution).length:1+Math.max(1,Math.ceil(rows.length/28));
   $('#exportEstimate').textContent=form.elements.format.value==='PNG'?(n===1?'One continuous PNG image':`${n} numbered PNG pages in one ZIP`):`${n} PDF pages · map + complete directory`;
  }
  $('#exportButton').disabled=false;
 }catch(err){$('#exportEstimate').textContent=err.message;$('#exportButton').disabled=true}
}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000)}
const blob64=blob=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(blob)});
function exportMapMarkup(){
 const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');
 drawMap(svg,S.country,true);
 if($('#mapSvg')){svg.innerHTML=$('#mapSvg').innerHTML;svg.querySelector('.map-transform')?.removeAttribute('transform')}
 svg.setAttribute('xmlns','http://www.w3.org/2000/svg');svg.setAttribute('viewBox','0 0 900 460');svg.setAttribute('width','1800');svg.setAttribute('height','920');
 svg.querySelectorAll('.region').forEach(node=>{node.setAttribute('stroke','#fff');node.setAttribute('stroke-width','1.1')});
 svg.querySelectorAll('text').forEach(node=>node.setAttribute('font-family','Arial, sans-serif'));
 return new XMLSerializer().serializeToString(svg);
}
async function submitExport(form){
 const fd=new FormData(form),button=$('#exportButton'),rows=exportRows(form);
 const destination=fd.get('destination');if(destination==='new'&&!String(fd.get('newProjectName')||'').trim())throw Error('Enter a name for the new project.');
 button.disabled=true;button.textContent='Creating complete report…';
 try{
  const source=project(),baseName=(source.name.replace(/[^a-z0-9_-]/gi,'-')||'Property-Map')+'-'+new Date().toISOString().slice(0,10)+'-'+Date.now().toString(36).slice(-4);
  const context={project:source,rows,countryName:S.countries.find(c=>c.code===S.country)?.name||S.country,mapFocus:[S.state,S.district].filter(Boolean).join(' / '),mapMode:S.mapMode,includeLegend:fd.has('legend'),includeDate:fd.has('date')};
  const resolution=Number(fd.get('resolution')),svg=exportMapMarkup();
  let blob,extension;
  if(fd.get('format')==='PDF'){blob=await ExportEngine.pdfBlob(context,exportColumns(rows,form),resolution,svg);extension='pdf'}
  else{
   const result=fd.get('pngLayout')==='poster'?
     await ExportEngine.posterBlob(context,Object.fromEntries(S.countries.map(c=>[c.code,c.name])),resolution,svg):
     await ExportEngine.pngBlob(context,exportColumns(rows,form),resolution,svg,baseName);
   blob=result.blob;extension=result.extension;
  }
  let dest=destination;
  if(dest==='new'){
   const np=clone(source);np.name=String(fd.get('newProjectName')).trim();np.demo=false;np.fields=getFields().map(f=>({...f,locked:false}));np.properties=rows.map(clone);np.country=S.country;
   const created=await api('/api/projects','POST',np);S.projects.push(created);dest=created.id;
  }
  const name=baseName+'.'+extension;
  const saved=await api('/api/projects/'+dest+'/exports','POST',{name,mime:blob.type,data:await blob64(blob)});
  S.projects=S.projects.map(x=>x.id===saved.id?saved:x);
  if(fd.has('download'))downloadBlob(blob,name);
  closeDrawer(true);toast(`${rows.length} properties exported to ${saved.name}`);await render();
 }finally{if($('#exportButton')){$('#exportButton').disabled=false;$('#exportButton').textContent='Export complete report'}}
}
async function downloadExport(eid){if(window.STANDALONE){const e=await storeBlob(eid);if(!e)throw Error('Export file was removed from this browser. Generate it again.');const raw=Uint8Array.from(atob(e.data),c=>c.charCodeAt(0));downloadBlob(new Blob([raw],{type:e.mime}),e.name)}else{const r=await fetch('/api/exports/'+eid);if(!r.ok)throw Error('Export is unavailable.');const e=S.projects.flatMap(p=>p.exports).find(e=>e.id===eid);downloadBlob(await r.blob(),e?.name||'export')}}
function backup(){const {accountName,displayName,...config}=S.config,projects=S.projects.map(({owner,members,access,effectiveFields,...p})=>p);downloadBlob(new Blob([JSON.stringify({format:'property-map',version:2,date:new Date().toISOString(),config,projects},null,2)],{type:'application/json'}),'Property-Map-Backup.json');toast('Backup downloaded')}
async function importBackup(file){const b=JSON.parse(await file.text());if(b.format!=='property-map'||!Array.isArray(b.projects)||!b.projects.length)throw Error('Choose a Property Map backup containing at least one project.');if(b.projects.length>50)throw Error('Import up to 50 projects at a time.');const projects=b.projects.map(raw=>{const p=clone(raw);if(!p||typeof p!=='object')throw Error('The backup contains an invalid project.');p.name=String(p.name||'').trim()+' (imported)';p.description=String(p.description||'');p.fields=[...(b.config?.fields||[]),...(b.config?.teamFields?.[p.team]||[]),...(p.fields||[])].filter((v,i,a)=>v&&a.findLastIndex(x=>x.id===v.id)===i);p.properties=(p.properties||[]).map(r=>({...r,id:r.id||id(),custom:r.custom&&typeof r.custom==='object'?r.custom:{}}));p.palette=p.palette||clone(S.config.palette||paletteFrom(PRESETS.Classic));p.regionRules=p.regionRules||{};return ensureProjectLegends(p)});const saved=await api('/api/import','POST',{projects});S.projects.push(...saved.map(ensureProjectLegends));toast(saved.length+' project'+(saved.length===1?'':'s')+' imported');await render()}
function csv(){const q=v=>'"'+String(v??'').replaceAll('"','""').replace(/^[=+@-]/,"'$&")+'"';const core=[['name','Property name'],['code','Property code'],['country','Country'],['state','State / Province'],['district','District / County'],['city','City'],['status','Status'],['team','Team'],['lat','Latitude'],['lng','Longitude']],custom=getFields().filter(f=>fieldAllowed(f)).map(f=>[f.id,f.label]);const header=[...core.map(x=>x[1]),...custom.map(x=>x[1])],text=[header.map(q).join(','),...filtered().map(r=>[...core.map(([k])=>r[k]),...custom.map(([k])=>r.custom?.[k])].map(q).join(','))].join('\r\n');downloadBlob(new Blob(['\ufeff'+text],{type:'text/csv;charset=utf-8'}),'Property-Directory.csv')}
async function action(a,el){
 if(a==='close')return closeDrawer();if(a==='reload'){await reload();return render()}
 if(a==='nav'){S.view=el.dataset.view;S.search='';S.page=1;return render()}
 if(a==='open-project'){S.project=el.dataset.id;S.country=project().country;S.state='';S.district='';S.search='';S.page=1;S.view='workspace';return render()}
 if(a==='edit-project')return projectDrawer(el.dataset.id);
 if(a==='delete-project'){if(!confirm('Delete this project and its saved exports? This cannot be undone.'))return;await api('/api/projects/'+el.dataset.id,'DELETE');S.projects=S.projects.filter(p=>p.id!==el.dataset.id);if(S.project===el.dataset.id)S.project=S.projects[0]?.id||null;closeDrawer(true);S.view='projects';toast('Project deleted');return render()}
 if(a==='mapmode'){S.mapMode=el.dataset.mode;return render()}
 if(a==='clear'){S.state='';S.district='';S.search='';S.page=1;return render()}
 if(a==='region-select')return selectRegion(el.dataset.state);
 if(a==='property')return propertyDrawer(el.dataset.id);
 if(a==='new-project')return newProject();if(a==='legends'||a==='region')return legendsDrawer(S.country,S.state);if(a==='colors')return colorsDrawer();if(a==='export')return exportDrawer();if(a==='csv')return csv();if(a==='backup')return backup();if(a==='import')return $('#importFile').click();
 if(a==='review-export-list'){document.querySelector('#exportRecords')?.scrollIntoView({behavior:'smooth',block:'start'});return}
 if(a==='next'){S.page++;return render()}if(a==='prev'){S.page--;return render()}
 if(a.startsWith('zoom-')){const el=$('#mapSvg');if(!el)return;const svg=d3.select(el);if(a==='zoom-reset')svg.transition().duration(200).call(el._zoom.transform,d3.zoomIdentity);else svg.transition().duration(200).call(el._zoom.scaleBy,a==='zoom-in'?1.35:1/1.35);return}
 if(a==='preset'){S.colorDraft=paletteFrom(PRESETS[el.dataset.preset]);refreshColorInputs();$$('.palette-card').forEach(x=>x.classList.toggle('selected',x===el));return}
 if(a==='reset-colors'){S.colorDraft=clone(S.config.palette);return refreshColorInputs()}
 if(a==='generate-palette')return generatePalette();if(a==='use-generated'){S.colorDraft=paletteFrom(S.generated);return refreshColorInputs()}
 if(a==='apply-colors'){if(!Object.values(S.colorDraft).every(v=>/^#[0-9a-fA-F]{6}$/.test(v)))throw Error('Use a six-digit hex color, such as #7052d6.');const p=clone(project());p.palette=clone(S.colorDraft);if($('#paletteScope').value==='account'){if(S.user.role!=='admin')throw Error('Only an admin can set account defaults.');const cfg=clone(S.config);cfg.palette=clone(S.colorDraft);await api('/api/config','PUT',cfg);S.config=cfg}await saveProject(p,'Your palette is applied');closeDrawer(true);return render()}
 if(a==='settings-tab'){S.settingsTab=el.dataset.tab;return render()}
 if(a==='add-legend')return legendDefinitionDrawer();
 if(a==='edit-legend')return legendDefinitionDrawer(el.dataset.id);
 if(a==='delete-legend'){const p=clone(project());if(p.legends.length===1)throw Error('Keep at least one map legend.');const item=p.legends.find(x=>x.id===el.dataset.id),replacement=p.legends.find(x=>x.id!==el.dataset.id);if(!item)return;if(!confirm(`Delete “${item.label}”? Existing uses will be reassigned to “${replacement.label}”.`))return;p.legends=p.legends.filter(x=>x.id!==item.id);p.properties.forEach(r=>{if(propertyLegendId(r,p)===item.id)r.legendId=replacement.id});Object.values(p.regionRules||{}).forEach(rule=>{if(rule.legendId===item.id)rule.legendId=replacement.id});await saveProject(p,'Map legend deleted');return legendsDrawer(S.legendCountry,S.legendState)}
 if(a==='edit-region-legend'){const key=el.dataset.key,cut=key.indexOf(':');return legendsDrawer(key.slice(0,cut),key.slice(cut+1))}
 if(a==='delete-region-legend'){if(!confirm('Remove this regional legend assignment?'))return;const p=clone(project());delete p.regionRules[el.dataset.key];await saveProject(p,'Regional legend assignment removed');return legendsDrawer(S.legendCountry,S.legendState)}
 if(a==='add-field'||a==='edit-field')return fieldDrawer(el.dataset.id);
 if(a==='remove-field'){if(!confirm('Remove this field from the form? Stored values will be preserved.'))return;return saveFieldList(scopedFields().filter(f=>f.id!==el.dataset.id))}
 if(a==='delete-property'){if(!confirm('Delete this property from the project?'))return;const p=clone(project());p.properties=p.properties.filter(r=>r.id!==el.dataset.id);await saveProject(p,'Property deleted');closeDrawer(true);return render()}
 if(a==='share')return shareDrawer(el.dataset.id);
 if(a==='add-user')return userDrawer();
 if(a==='logout'){await api('/api/logout','POST');return login()}
 if(a==='download-export')return downloadExport(el.dataset.id);
 if(a==='delete-export'){if(!confirm('Delete this saved export?'))return;const saved=await api('/api/exports/'+el.dataset.id,'DELETE');S.projects=S.projects.map(p=>p.id===saved.id?saved:p);toast('Export deleted');return render()}
 if(a==='help')return drawer('A little orientation','Everything you need to get started.',`<div class="stack"><div><h3>01 / Make it yours</h3><p class="sub">Open Projects to create a project. Add properties, then explore by country, state, or county.</p></div><div><h3>02 / Find your perspective</h3><p class="sub">Property count shades regions by volume. Regional status shows classifications and competition. Locations plots only properties with entered coordinates.</p></div><div><h3>03 / Share a snapshot</h3><p class="sub">Export PNG or PDF and save it to a project. Choose a detailed PDF/PNG directory or a single PNG with the map beside a grouped property list. Both include every property in the selected scope.</p></div><div class="hint">Map data: Natural Earth admin-1, generalised for display, and US Census via us-atlas (2017 county boundaries). Boundaries may differ from current official administrative records. Other countries allow district names to be entered manually.</div><p class="sub"><a href="https://www.naturalearthdata.com/about/terms-of-use/" target="_blank" rel="noopener">Natural Earth — public domain</a><br><a href="https://github.com/topojson/us-atlas" target="_blank" rel="noopener">US Atlas — source and attribution</a><br>Libraries: D3 (ISC), topojson-client (ISC), pdf-lib (MIT), JSZip (MIT).</p></div>`,btn('Got it','close','','primary'));
}
