 if(el.id==='fieldScope'){S.fieldScope=el.value;await render()}
 if(el.id==='legendCountry'){await geo(el.value);S.legendCountry=el.value;S.legendState='';const state=$('#legendState');state.innerHTML=options(regionNames(S.geo[el.value]),'','Select a state or province')}
 if(el.id==='legendState')S.legendState=el.value;
