 if(f.id==='fieldForm'){const fd=new FormData(f),v={...S.fieldDraft,label:fd.get('label').trim(),type:fd.get('type'),visibility:fd.get('visibility'),editable:fd.get('editable'),condition:fd.get('condition'),required:fd.has('required'),locked:fd.has('locked'),options:[...new Set(fd.get('options').split('\n').map(x=>x.trim()).filter(Boolean))]};if(v.type==='select'&&!v.options.length)throw Error('Add at least one dropdown option.');if(v.required&&v.visibility!==v.editable)throw Error('Required fields must be editable by every role that can see them.');const fs=clone(scopedFields());if(fs.some(x=>x.id===v.id))fs.splice(fs.findIndex(x=>x.id===v.id),1,v);else fs.push(v);await saveFieldList(fs)}
 if(f.id==='legendForm'){const fd=new FormData(f),p=clone(project()),label=String(fd.get('label')||'').trim(),color=String(fd.get('color')||'');if(!label)throw Error('Enter a legend name.');if(p.legends.some(x=>x.id!==S.editingLegend&&x.label.toLowerCase()===label.toLowerCase()))throw Error('Legend names must be unique.');if(S.editingLegend){const item=p.legends.find(x=>x.id===S.editingLegend);item.label=label;item.color=color}else{let lid=label.toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,40)||'legend';const base=lid;let n=2;while(p.legends.some(x=>x.id===lid))lid=base+'-'+n++;p.legends.push({id:lid,label,color})}await saveProject(p,'Map legend saved');closeDrawer(true);await render();return legendsDrawer(S.legendCountry,S.legendState)}
 if(f.id==='legendAssignForm'){const fd=new FormData(f),country=String(fd.get('country')),state=String(fd.get('state')),legendId=String(fd.get('legendId'));if(!state)throw Error('Choose a state or province.');const p=clone(project());p.regionRules??={};p.regionRules[country+':'+state]={legendId,competition:fd.has('competition')};await saveProject(p,'Map legend applied to '+state);S.country=country;S.state=state;S.mapMode='status';closeDrawer(true);await render();return legendsDrawer(country,state)}
 if(f.id==='teamForm'){const fd=new FormData(f),cfg=clone(S.config);cfg.teams=[...new Set(String(fd.get('teams')||'').split('\n').map(x=>x.trim()).filter(Boolean))];if(!cfg.teams.length)throw Error('Add at least one team.');await api('/api/config','PUT',cfg);S.config=cfg;toast('Teams saved');await render()}
